    AudioHost audio{*core};Worker control,files;Recorder recorder{*core,files};Broadcaster broadcast{*core};Session session;
    HWND window=nullptr,pane=nullptr,statusLabel=nullptr,startButton=nullptr,metrics=nullptr,recordStatus=nullptr,broadcastStatus=nullptr;
    HFONT font=nullptr,titleFont=nullptr,smallFont=nullptr;HBRUSH pageBrush=CreateSolidBrush(background),fieldBrush=CreateSolidBrush(surface);
    UINT dpi=96;int page=0,scroll=0,contentHeight=0,nextId=1000,fxSource=0,selectedPad=0,fxStage=0;bool building=false,dirty=false,recordPending=false,initialized=false,testMode=false;int smokePage=0;std::atomic<bool> closing{false};
    std::vector<Position> positions;std::vector<HWND> nav;std::vector<Endpoint> devices;std::vector<Program> processes;uint32_t selectedProcess=0;
    std::unordered_map<int,std::function<void()>> commands;std::unordered_map<HWND,std::function<void(int)>> sliders;std::vector<std::pair<HWND,int>> meters;
    std::filesystem::path directory,clipsFolder,takesFolder;std::wstring notice=L"Loading your studio…";BroadcastConfig broadcastConfig;
    std::array<HWND,23> fxFields{};HWND orderList=nullptr;
